#!/usr/bin/env bash

set -euo pipefail

IN_THREE_ROOT="${IN_THREE_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
STATE_DIR="$IN_THREE_ROOT/.state"
STATE_FILE="$STATE_DIR/config"

die() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

note() {
  printf '\033[1;35m->\033[0m %s\n' "$*"
}

success() {
  printf '\033[1;32m✓\033[0m %s\n' "$*"
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || die "missing required command: $1"
}

load_state() {
  [[ -f "$STATE_FILE" ]] || die "no provisioned host found; run ./farcaster provision first"
  # State is generated by our provisioner and is owner-readable only.
  # shellcheck disable=SC1090
  source "$STATE_FILE"
  : "${SERVER_IP:?missing SERVER_IP in state}"
  : "${SSH_KEY:?missing SSH_KEY in state}"
  : "${SSH_USER:=inthree}"
}

ssh_args() {
  printf '%s\n' \
    "-i" "$SSH_KEY" \
    "-o" "IdentitiesOnly=yes" \
    "-o" "StrictHostKeyChecking=accept-new" \
    "-o" "ConnectTimeout=10"
}

remote() {
  local args=()
  mapfile -t args < <(ssh_args)
  # Commands are assembled locally from trusted state and fixed script inputs.
  # shellcheck disable=SC2029
  ssh "${args[@]}" "$SSH_USER@$SERVER_IP" "$@"
}

copy_to() {
  local source="$1"
  local destination="$2"
  local args=()
  mapfile -t args < <(ssh_args)
  scp "${args[@]}" "$source" "$SSH_USER@$SERVER_IP:$destination"
}

wait_for_ssh() {
  local attempts="${1:-60}"
  local args=()
  mapfile -t args < <(ssh_args)
  for ((i = 1; i <= attempts; i++)); do
    if ssh "${args[@]}" "$SSH_USER@$SERVER_IP" true >/dev/null 2>&1; then
      return 0
    fi
    sleep 5
  done
  return 1
}
